css:
/* PDF Viewer styles */
    #pdfViewer {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0, 0, 0, 0.9);
      z-index: 1000;
      padding: 2rem;
      color: white;
      overflow-y: auto;
    }

    #pdfClose {
      position: absolute;
      right: 2rem;
      top: 2rem;
      background: none;
      border: none;
      color: white;
      font-size: 2rem;
      cursor: pointer;
    }

    #pdfTitle {
      margin-bottom: 2rem;
      padding-right: 3rem;
    }

    .pdf-pages {
      display: flex;
      flex-direction: column;
      gap: 2rem;
      align-items: center;
    }

    .pdf-page {
      background: white;
      padding: 1rem;
      border-radius: 4px;
      box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    }

    .page-number {
      text-align: center;
      margin-top: 0.5rem;
      color: #fff;
    }

    .pdf-loading {
      text-align: center;
      padding: 2rem;
    }

    .pdf-loading-progress {
      position: fixed;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      background: rgba(0, 0, 0, 0.8);
      color: white;
      padding: 1rem 2rem;
      border-radius: 4px;
      z-index: 1100;
    }

    .more-pages {
      text-align: center;
      padding: 1rem;
      background: rgba(255, 255, 255, 0.1);
      border-radius: 4px;
      margin-top: 1rem;
    }

    /* Page-specific styles */
    .library-container {
      padding: 2rem;
      max-width: 1400px;
      margin: 0 auto;
    }

    /* Subject Cards */
    .subject-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 2rem;
      margin-top: 2rem;
    }

    .subject-card {
      background: #fff;
      border-radius: 16px;
      box-shadow: 0 4px 16px rgba(0,0,0,0.06);
      overflow: hidden;
      position: relative;
      transition: all 0.3s ease;
      cursor: pointer;
    }

    .subject-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 8px 24px rgba(0,0,0,0.12);
    }

    .subject-banner {
      height: 140px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      position: relative;
    }

    .subject-banner i {
      font-size: 3.5rem;
      position: relative;
      z-index: 1;
    }

    .subject-banner--math {
      background: linear-gradient(45deg, #2563eb, #3b82f6);
    }

    .subject-banner--physics {
      background: linear-gradient(45deg, #7c3aed, #a855f7);
    }

    .subject-banner--chemistry {
      background: linear-gradient(45deg, #059669, #10b981);
    }

    .subject-banner--biology {
      background: linear-gradient(45deg, #0ea5e9, #38bdf8);
    }

    .subject-banner--english {
      background: linear-gradient(45deg, #f97316, #fb923c);
    }

    .subject-content {
      padding: 1.5rem;
    }

    .subject-name {
      font-size: 1.5rem;
      font-weight: 600;
      color: #1e3a8a;
      margin: 0 0 0.5rem 0;
    }

    .subject-info {
      display: flex;
      align-items: center;
      gap: 1rem;
      color: #64748b;
      font-size: 0.9rem;
    }

    /* Subject Sections */
    .subject-section {
      display: none;
      background: #fff;
      border-radius: 16px;
      box-shadow: 0 4px 16px rgba(0,0,0,0.06);
      overflow: hidden;
      padding: 2rem;
      margin-top: 2rem;
    }

    .subject-section.active {
      display: block;
    }

    .subject-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 2rem;
    }

    .subject-header-left {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    .subject-meta {
      color: #64748b;
      font-size: 0.9rem;
      margin-top: 0.25rem;
    }

    .resources-list {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
      gap: 1.5rem;
      margin-top: 1rem;
    }

    .back-button {
      background: none;
      border: none;
      color: #64748b;
      font-size: 0.9rem;
      padding: 0.5rem;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 0.5rem;
      transition: color 0.2s;
    }

    .back-button:hover {
      color: #2563eb;
    }

    /* Resource Items */
    .resource-item {
      background: #fff;
      border: 1px solid #e5e7eb;
      border-radius: 8px;
      padding: 1.5rem;
      transition: all 0.2s ease;
    }

    .resource-item:hover {
      border-color: #2563eb;
      box-shadow: 0 4px 12px rgba(37, 99, 235, 0.1);
    }

    .resource-item h3 {
      color: #1e3a8a;
      font-size: 1.125rem;
      margin: 0 0 0.5rem 0;
    }

    .resource-item p {
      color: #64748b;
      font-size: 0.875rem;
      margin: 0 0 1rem 0;
    }

    .resource-item button {
      background: #2563eb;
      color: white;
      border: none;
      padding: 0.5rem 1rem;
      border-radius: 4px;
      font-size: 0.875rem;
      cursor: pointer;
      transition: background-color 0.2s;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }

    .resource-item button:hover {
      background: #1d4ed8;
    }

    /* PDF Viewer */
    #pdfViewer {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.95);
      z-index: 1000;
      display: none;
      padding: 2rem;
    }

    #pdfContainer {
      max-width: 1000px;
      margin: 0 auto;
      background: white;
      border-radius: 8px;
      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
      overflow: auto;
      height: calc(100vh - 8rem);
      padding: 2rem;
    }

    .pdf-pages {
      padding: 2rem;
    }

    .pdf-page {
      margin-bottom: 2rem;
      position: relative;
    }

    .pdf-page canvas {
      width: 100%;
      height: auto;
      display: block;
      border: 1px solid #e5e7eb;
      border-radius: 4px;
    }

    .page-number {
      position: absolute;
      bottom: 0.5rem;
      right: 0.5rem;
      background: rgba(0, 0, 0, 0.6);
      color: white;
      padding: 0.25rem 0.5rem;
      border-radius: 4px;
      font-size: 0.875rem;
    }

    .more-pages {
      text-align: center;
      padding: 1rem;
      background: #f9fafb;
      border-radius: 4px;
      margin-top: 1rem;
      color: #4b5563;
    }

    .pdf-loading {
      text-align: center;
      padding: 2rem;
    }

    .pdf-loading i {
      margin-bottom: 1rem;
    }

    #pdfTitle {
      color: white;
      text-align: center;
      padding: 1rem;
      margin: 0;
      font-size: 1.25rem;
    }

    #pdfClose {
      position: absolute;
      top: 1rem;
      right: 1rem;
      background: none;
      border: none;
      color: white;
      font-size: 1.5rem;
      cursor: pointer;
      padding: 0.5rem;
      width: 40px;
      height: 40px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 50%;
      transition: background-color 0.2s;
    }

    #pdfClose:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    .pdf-error {
      color: #dc2626;
    }

    .pdf-error-message {
      font-size: 0.8em;
      margin-top: 0.5em;
    }
